  'European History (Survey)',
  'A survey of European history from antiquity and the Middle Ages to the post-1989 era. Students interpret primary sources, connect political, social, cultural, economic, religious, gender, imperial, and intellectual history in one timeline, compare western, eastern, northern, southern, and borderland experiences, and analyze how Europe shaped and was shaped by global exchange, empire, migration, war, and decolonization.',
  $eursjson${"slug": "european-history-survey", "title": "European History (Survey)", "description": "A survey of European history from antiquity and the Middle Ages to the post-1989 era. Students interpret primary sources, connect political, social, cultural, economic, religious, gender, imperial, and intellectual history in one timeline, compare western, eastern, northern, southern, and borderland experiences, and analyze how Europe shaped and was shaped by global exchange, empire, migration, war, and decolonization.", "topics": [{"id": "a89291e3-8b1d-4d14-8808-15738df1b881", "type": "topic", "title": "Historical Method, Geography, and Periodization", "description": "Frame Europe as a changing historical category and learn how historians build arguments from sources, chronology, geography, and interpretation.", "children": [{"id": "d969d164-adc2-4435-9999-f4cba8a604f8", "type": "subtopic", "title": "Europe as a historical category", "children": [{"id": "9bab3c7b-7b0e-4776-9d19-8cc42ac5b841", "type": "concept", "title": "Geographic Europe and cultural Europe"}, {"id": "1eaead6c-eb91-478c-8fe3-3d3b7559f612", "type": "concept", "title": "Mediterranean, Atlantic, Baltic, and Eurasian frames"}, {"id": "f6349f7a-6fae-49b8-ace0-f2dc8e7e0bec", "type": "concept", "title": "Center, periphery, and borderlands"}, {"id": "ac163709-c5b7-4919-9f8c-ffa872ffdbfb", "type": "concept", "title": "Europe in world history rather than Europe alone"}], "description": "Students begin by questioning what Europe is, where its borders are drawn, and why those answers change over time."}, {"id": "e440ccac-2838-464f-9823-9a2b25006053", "type": "subtopic", "title": "Sources and historical interpretation", "children": [{"id": "09f77d89-200a-417f-9574-956e365f6d88", "type": "concept", "title": "Primary and secondary sources"}, {"id": "81117aaa-e034-4728-a21e-10cdef2d10db", "type": "concept", "title": "Chronology and causation"}, {"id": "8e8a4be6-99dc-42ab-a3f7-f8d2123c4882", "type": "concept", "title": "Bias, silence, and perspective"}, {"id": "046feda9-27cd-462d-9673-8180592decb4", "type": "concept", "title": "Historiography and competing interpretations"}], "description": "Survey history becomes richer when students learn how evidence is made, preserved, translated, and argued over."}, {"id": "47b252c4-aec2-465f-ae42-c8102da6748b", "type": "subtopic", "title": "Periodization and scale", "children": [{"id": "cba12a71-eb43-4e1f-b34b-69ce1633164e", "type": "concept", "title": "Ancient, medieval, early modern, modern, and contemporary"}, {"id": "026c1b75-8bf8-43bf-8cd4-ff7f7ad978f8", "type": "concept", "title": "Local, regional, national, imperial, and global scales"}, {"id": "e8ab5ed7-927f-4b69-8c7a-44efd4916dbd", "type": "concept", "title": "Continuity and change"}, {"id": "1667dfc8-421b-469b-bcf7-886282ad70c7", "type": "concept", "title": "Survey maps, timelines, and comparative cases"}], "description": "Periods are tools, not facts; students learn when labels like medieval, early modern, and modern clarify or distort the past."}]}, {"id": "261ca472-876b-4c83-b6c4-5878d40c862f", "type": "topic", "title": "Classical, Late Antique, and Christian Foundations", "description": "Trace Greek, Roman, Jewish, Christian, and late antique inheritances that shaped later European institutions, identities, and debates.", "children": [{"id": "b96ab614-a5e4-4786-9b6a-e7e5cc851a87", "type": "subtopic", "title": "Greek and Roman political inheritances", "children": [{"id": "e7081f31-703e-46e6-bf95-f1e1beee1608", "type": "concept", "title": "Athenian democracy and citizenship"}, {"id": "f789eca6-08ce-4fc1-ad55-867e3e843b08", "type": "concept", "title": "Roman republic and empire"}, {"id": "2f55c616-49c1-44c1-9907-f25ab641633b", "type": "concept", "title": "Law, citizenship, and administration"}, {"id": "8629dd0a-fbcc-4d1e-80d9-d03d64dd9483", "type": "concept", "title": "Classical memory in later Europe"}], "description": "This subtopic introduces political forms and civic languages later Europeans repeatedly revived, contested, and reinvented."}, {"id": "56e29d8f-40d3-4124-82e0-fbaa89f92e05", "type": "subtopic", "title": "Late antiquity and transformation", "children": [{"id": "7f816ff3-80a9-4bfe-a18e-29d816169400", "type": "concept", "title": "Imperial crisis and reform"}, {"id": "7b93a6b0-787a-413a-bde7-c1d968aaacc8", "type": "concept", "title": "Germanic kingdoms"}, {"id": "6221fe68-c9d2-4aba-ac2d-754b9bfd7f7f", "type": "concept", "title": "Continuity of Roman law and cities"}, {"id": "135d9d4f-1b63-4ce6-b2ac-0c173c319f80", "type": "concept", "title": "Migration, settlement, and cultural blending"}], "description": "Late antiquity shows that Rome did not simply fall; institutions, religions, economies, and identities were transformed over centuries."}, {"id": "86231387-b096-44b1-9537-e0c78ebbad3f", "type": "subtopic", "title": "Christianity and religious authority", "children": [{"id": "c5422582-6709-49ed-9049-b442ff039ec3", "type": "concept", "title": "Church hierarchy and councils"}, {"id": "430bad4d-b7af-42a6-be0a-2a6a4a686914", "type": "concept", "title": "Monasticism"}, {"id": "f42d3ee8-261b-4ea2-9bac-ddd30b8fa727", "type": "concept", "title": "Augustine and Christian political thought"}, {"id": "eed7ddb6-cb68-44ff-9b5d-b3bd8ab4f02a", "type": "concept", "title": "Judaism, Christianity, and religious minorities"}], "description": "Christian institutions became major forces in education, welfare, law, kingship, art, and conflict."}]}, {"id": "d44985a8-a0db-48b8-bcd1-cf73f46264b3", "type": "topic", "title": "Early Medieval Europe, Byzantium, Islam, and Post-Roman Worlds", "description": "Study political fragmentation, religious expansion, cultural exchange, and the making of medieval societies after Rome.", "children": [{"id": "fda26036-2737-45db-be6b-b79021554a46", "type": "subtopic", "title": "Post-Roman kingdoms and Carolingian Europe", "children": [{"id": "76ce2dfb-8c96-4661-8d42-80d300c40274", "type": "concept", "title": "Frankish expansion"}, {"id": "9b09e0d6-fe03-4a76-accf-115e1408e4de", "type": "concept", "title": "Carolingian renaissance"}, {"id": "ba289187-ecb6-4ccc-8900-2ce864a864bc", "type": "concept", "title": "Manorialism and local lordship"}, {"id": "a49638f9-1e1d-4416-9103-2328738aeb4a", "type": "concept", "title": "Kingship, oath, and loyalty"}], "description": "Students examine how new kingdoms created authority from Roman, Christian, Germanic, and local traditions."}, {"id": "89e20be7-0ad3-4f42-aaa7-0b82aeef862c", "type": "subtopic", "title": "Byzantium and eastern Christianity", "children": [{"id": "1a11d2fa-18e0-4e14-a1e5-b0f044b97fcc", "type": "concept", "title": "Constantinople and imperial government"}, {"id": "f0049041-6ed1-482d-a247-84b3afa94e90", "type": "concept", "title": "Orthodox Christianity"}, {"id": "74d7c762-c458-4d80-ba89-aacd05a1c07a", "type": "concept", "title": "Iconoclasm and church-state relations"}, {"id": "cfa44a89-42b2-41d2-befe-c17b31675234", "type": "concept", "title": "Diplomacy with Slavs, Arabs, and Latins"}], "description": "Byzantium keeps eastern Europe and the Mediterranean in the survey, complicating a western-only story of Europe."}, {"id": "503a14d5-daa8-444d-99d3-5a4a1f4a9c95", "type": "subtopic", "title": "Islamic worlds and European exchange", "children": [{"id": "ce838724-9cf0-4759-b320-dd0eebcae1b5", "type": "concept", "title": "Al-Andalus and Sicily"}, {"id": "c21e5bcc-22d6-412e-aadf-c8a6d195a2ab", "type": "concept", "title": "Mediterranean trade"}, {"id": "29d51231-680a-4b54-a6b5-544af7158a02", "type": "concept", "title": "Translation movements"}, {"id": "8d6ab4e1-7173-468e-b6a5-c42ba6c40ff3", "type": "concept", "title": "Jewish, Christian, and Muslim coexistence and conflict"}], "description": "Islamic expansion connected Europe to wider Afro-Eurasian worlds through conflict, trade, science, translation, and coexistence."}]}, {"id": "aa17796c-0870-4635-9efd-d3834f40e93b", "type": "topic", "title": "High Medieval Europe: Lordship, Cities, Universities, and Crusades", "description": "Analyze the growth of feudal, urban, ecclesiastical, commercial, and intellectual institutions from roughly 1000 to 1300.", "children": [{"id": "099fb239-4388-40ac-b997-8662e3e8e728", "type": "subtopic", "title": "Lordship, peasants, and medieval society", "children": [{"id": "b57469d6-6024-44db-aa9a-66853e1e23c7", "type": "concept", "title": "Feudal relationships"}, {"id": "5586a6e8-11ba-4471-9ea9-633868e1e058", "type": "concept", "title": "Manors and peasant obligations"}, {"id": "458178d9-8298-41fc-84de-d3192537d1cf", "type": "concept", "title": "Nobility and chivalry"}, {"id": "e2e50f05-8893-46a9-b7f2-f8f8a0ae53f3", "type": "concept", "title": "Village life and customary rights"}], "description": "This subtopic explains how power and production worked in a mostly agrarian world."}, {"id": "6a40b52c-d892-437b-b45a-f80ab0056a10", "type": "subtopic", "title": "Urban revival, commerce, and universities", "children": [{"id": "f8ed783d-007b-4b6e-a20c-d8da970ce74f", "type": "concept", "title": "Guilds and merchant networks"}, {"id": "cb8057d4-07a2-4d07-bb57-78957c407bd1", "type": "concept", "title": "Italian city-states and the Hanseatic League"}, {"id": "17212f87-c73a-420c-a68b-492f4c21c941", "type": "concept", "title": "Universities and scholasticism"}, {"id": "59ed2edc-310f-48e9-a9f8-b91d45af0945", "type": "concept", "title": "Canon law and professional learning"}], "description": "Students see medieval Europe as dynamic, commercial, literate, and institutionally creative."}, {"id": "d9d7d67f-9537-400f-9e3c-b0524240dbba", "type": "subtopic", "title": "Church reform and crusading", "children": [{"id": "010b0d52-6110-4ae7-8efd-463bf0d57a43", "type": "concept", "title": "Gregorian reform"}, {"id": "3dbbb4e5-04e1-4d70-b421-5e9fcef5d873", "type": "concept", "title": "Pilgrimage and holy war"}, {"id": "9f34e85c-f4d3-4ad1-b50f-466ae4d87559", "type": "concept", "title": "Crusader states"}, {"id": "1bf24147-4da0-4983-a284-29dd612a9f34", "type": "concept", "title": "Persecution of Jews, heretics, and religious others"}], "description": "The crusades reveal how piety, violence, papal authority, colonization, and cross-cultural contact could merge."}]}, {"id": "512e5f64-87b1-463f-827e-b454e7bd47ab", "type": "topic", "title": "Late Medieval Crisis, Renaissance, and Humanism", "description": "Connect plague, war, social conflict, state consolidation, urban culture, art, and humanist learning in the transition to early modern Europe.", "children": [{"id": "f713efe6-3f40-4a9d-8096-e6aedb415cb6", "type": "subtopic", "title": "Plague, war, and social disruption", "children": [{"id": "b71c7abd-67d1-401d-80d1-42b72b9a9444", "type": "concept", "title": "Black Death"}, {"id": "2728e47b-354c-4a00-9b27-2447961b13de", "type": "concept", "title": "Hundred Years' War"}, {"id": "d9e17649-1b42-4f8d-b763-9e13a02841c1", "type": "concept", "title": "Peasant revolts and labor scarcity"}, {"id": "b6ee93a4-d07e-4149-b34b-2a00f877f552", "type": "concept", "title": "Crisis of church authority"}], "description": "The fourteenth century teaches students how demographic shock can transform labor, power, belief, and social conflict."}, {"id": "8b03c5fe-2d96-47e0-9ba2-b20d9cd150d7", "type": "subtopic", "title": "Renaissance culture and humanism", "children": [{"id": "0e2dba97-e28f-4ddc-9565-4c32fe898185", "type": "concept", "title": "Classical revival"}, {"id": "f3104078-16b3-4d68-9793-3e765f5176c6", "type": "concept", "title": "Civic humanism"}, {"id": "2bdc369f-3aa3-401a-a98b-62b3d1ef06b1", "type": "concept", "title": "Patronage and art"}, {"id": "f50e7a88-7514-41b5-aeb8-d116cded6d57", "type": "concept", "title": "Printing and manuscript cultures"}], "description": "The Renaissance is treated not as a miracle but as an urban, textual, artistic, political, and social movement."}, {"id": "fe7734f8-64c2-4a84-ab01-04a6bfa4964c", "type": "subtopic", "title": "State consolidation and political thought", "children": [{"id": "59ddacde-4d02-4bb8-abdf-bc57a5994e2f", "type": "concept", "title": "New monarchies"}, {"id": "ac92d093-9024-46d8-85be-38850da775ec", "type": "concept", "title": "Italian diplomacy"}, {"id": "416036b9-e9da-46d3-9c2f-dd54b06b083f", "type": "concept", "title": "Machiavelli and reason of state"}, {"id": "7eed4540-f4e9-45b5-b648-4dac3295bc50", "type": "concept", "title": "Courts, cities, and republics"}], "description": "Late medieval and Renaissance politics show the growth of taxation, diplomacy, bureaucracy, and realistic analysis of power."}]}, {"id": "791cf615-d0fb-4465-a980-b7665ca1b21f", "type": "topic", "title": "Reformation, Confessional Europe, and Wars of Religion", "description": "Understand how religious reform and confessional conflict transformed politics, culture, literacy, family life, and state power.", "children": [{"id": "2a8b1209-8374-4dad-a633-aec2a1404d09", "type": "subtopic", "title": "Protestant and Catholic reform", "children": [{"id": "f89937b0-294f-4633-aa23-c6e0d28ead31", "type": "concept", "title": "Luther, Calvin, and radical reform"}, {"id": "bb714688-854f-41f6-9042-81c7b4e5addd", "type": "concept", "title": "Catholic reform and Council of Trent"}, {"id": "5119d04b-305d-4cc9-b466-172fcda0cfc3", "type": "concept", "title": "Bible translation and print"}, {"id": "0b023f6f-225e-4468-913c-89401d80118d", "type": "concept", "title": "Education, discipline, and moral reform"}], "description": "Students learn how theological disputes became social, political, and cultural transformations."}, {"id": "2476fe0a-f0ed-48cd-b622-763e0060ef38", "type": "subtopic", "title": "Confessional states and everyday religion", "children": [{"id": "d8ef6cad-5b7a-467b-8aad-1346d37a3636", "type": "concept", "title": "Parish life and ritual"}, {"id": "bc02cee7-2760-4cbb-99c3-8db31bf2bfd0", "type": "concept", "title": "Marriage and household discipline"}, {"id": "1713462a-630d-4b7c-998f-08632a93adf9", "type": "concept", "title": "Witch hunts and popular belief"}, {"id": "224de0a8-f6bd-48a7-a11a-153db16717c6", "type": "concept", "title": "Religious minorities and toleration"}], "description": "Confessionalization shows how churches and states tried to shape belief, behavior, family, and community."}, {"id": "267d2bd1-20be-496d-9964-abb76bf6c717", "type": "subtopic", "title": "Wars of religion and settlement", "children": [{"id": "bf58fb9c-33a4-4fc1-9db5-7d5dec338448", "type": "concept", "title": "French Wars of Religion"}, {"id": "725fc82e-05f2-4c43-b626-adad44bcbfdf", "type": "concept", "title": "Dutch Revolt"}, {"id": "ed60f024-e718-4a75-983c-37ad86f87a79", "type": "concept", "title": "Thirty Years' War"}, {"id": "88d4ab1d-a05e-40ea-af7b-be69521530a2", "type": "concept", "title": "Peace of Westphalia"}], "description": "Religious conflict reorganized sovereignty and forced Europeans to rethink coexistence, authority, and violence."}]}, {"id": "c8feea3f-d94b-4e6c-b088-0f629c6fda27", "type": "topic", "title": "State Formation, Absolutism, Constitutionalism, and the Scientific Revolution", "description": "Compare early modern state power, constitutional conflict, global competition, and new ways of knowing nature and society.", "children": [{"id": "b0075a08-155d-48e0-bbb8-e6c3df059743", "type": "subtopic", "title": "Absolutism and fiscal-military states", "children": [{"id": "77dce281-5d77-47ab-8610-d4bb377a7463", "type": "concept", "title": "Louis XIV and Versailles"}, {"id": "3d91fe59-54e0-4e54-ac40-2da5636e7eb4", "type": "concept", "title": "Standing armies"}, {"id": "3941f691-f27d-4b9e-a223-1803f7b67c38", "type": "concept", "title": "Taxation and administration"}, {"id": "1c3bada9-85cb-496d-a782-8fd443f8df7a", "type": "concept", "title": "Mercantilism and empire"}], "description": "Students study how war, taxation, bureaucracy, and court culture expanded state power."}, {"id": "2ad75b3a-2baa-4a31-8432-7bea40340854", "type": "subtopic", "title": "Constitutional conflict and political rights", "children": [{"id": "01a9b6fd-9b71-44d9-87ec-a25b1c2d0dac", "type": "concept", "title": "English Civil Wars"}, {"id": "87c6da6a-595a-440f-8cf9-182d566ffca9", "type": "concept", "title": "Glorious Revolution"}, {"id": "fcae53b1-3656-4084-a8ba-c5ef7c3a3a4d", "type": "concept", "title": "Parliament and rights"}, {"id": "db724a39-b508-426a-9327-61ad8c3a6088", "type": "concept", "title": "Republicanism and mixed government"}], "description": "England, the Dutch Republic, and other cases reveal alternative paths to political authority."}, {"id": "5420eebb-2f0a-4284-9d00-7c6b196af2e9", "type": "subtopic", "title": "Scientific Revolution and knowledge", "children": [{"id": "d9ff6150-2c60-4656-a46a-8ffb8d8267dd", "type": "concept", "title": "Copernicus, Galileo, Newton, and Bacon"}, {"id": "4c118a86-8299-4a04-9552-3ded79e52e3b", "type": "concept", "title": "Scientific societies"}, {"id": "e6352035-4d0b-46b5-b18d-3fe32651e3f3", "type": "concept", "title": "Mechanism and experiment"}, {"id": "039c77f9-166e-41ce-9eca-9ce92811eff4", "type": "concept", "title": "Science, religion, and empire"}], "description": "New methods of observing nature transformed authority, technology, religion, and ideas of progress."}]}, {"id": "276d100d-6023-45d2-b422-c2bea55defa8", "type": "topic", "title": "Enlightenment, Atlantic Revolutions, and Napoleon", "description": "Assess how ideas of reason, rights, sovereignty, citizenship, race, empire, and revolution reshaped Europe and the Atlantic world.", "children": [{"id": "f00dd008-5420-44d2-867d-cde3e0da4d19", "type": "subtopic", "title": "Enlightenment thought and public culture", "children": [{"id": "8810ed79-19ff-4e98-a1f6-b0f0744bb722", "type": "concept", "title": "Salons, coffeehouses, and academies"}, {"id": "d5b2689c-6fa7-4c64-8dfc-09ea05676ddd", "type": "concept", "title": "Voltaire, Rousseau, Diderot, and Kant"}, {"id": "b0a1de69-8467-400d-ac5f-8e0ad01863db", "type": "concept", "title": "Natural rights and political economy"}, {"id": "fab812e8-7f36-4b7f-8366-a7a42dc451e9", "type": "concept", "title": "Limits of Enlightenment: gender, race, and empire"}], "description": "The Enlightenment introduces students to critique, sociability, print, reform, and debates over universal reason."}, {"id": "29e6f8a5-9841-462d-b79a-7e22ace0a222", "type": "subtopic", "title": "Revolutionary politics", "children": [{"id": "0a97de6f-00d3-4ca6-ad77-799df394ca9a", "type": "concept", "title": "American and French revolutionary contexts"}, {"id": "03ffaca5-df0b-41bc-91a0-b1e91d62c02e", "type": "concept", "title": "1789 and rights declarations"}, {"id": "e7e45da5-fdc0-43c1-ad1d-97e2f6c7454e", "type": "concept", "title": "Republicanism and terror"}, {"id": "1708362c-6e0b-498f-b329-85bee2681696", "type": "concept", "title": "Haitian Revolution and Atlantic slavery"}], "description": "Students compare how sovereignty shifted from monarchs to nations, citizens, constitutions, and armies."}, {"id": "849e0b6b-b7b3-41cc-b027-1b0e4af7613f", "type": "subtopic", "title": "Napoleonic Europe", "children": [{"id": "4d0c8157-2c67-416d-8406-1084b56da29b", "type": "concept", "title": "Napoleonic Code"}, {"id": "be9ed807-1c8c-4a7b-8ac2-849b7edab767", "type": "concept", "title": "Continental empire"}, {"id": "b9ac3062-ab2f-4f04-92ad-27a35b3289e3", "type": "concept", "title": "National resistance"}, {"id": "34658916-0360-4bfa-936e-2def7c86f737", "type": "concept", "title": "Congress of Vienna"}], "description": "Napoleon spread reform and domination at once, making him essential for understanding modern law, nationalism, and warfare."}]}, {"id": "67844f8e-931a-4dbf-8b38-f475f64209a1", "type": "topic", "title": "Industrial Revolution, Urbanization, and the Social Question", "description": "Explain industrial capitalism, labor, class, cities, public health, family economies, and new social movements.", "children": [{"id": "c88bf8a4-2898-4ad5-ba62-060a943564af", "type": "subtopic", "title": "Industrial capitalism", "children": [{"id": "84a180d1-dd7a-4568-b63f-898a2219d311", "type": "concept", "title": "Coal, steam, and factories"}, {"id": "d413a7ae-2954-48b0-a553-41b584a10fd4", "type": "concept", "title": "Textiles, iron, and railways"}, {"id": "37ef3e31-5355-415a-b1c5-8c1b9f4eb760", "type": "concept", "title": "Capital, banks, and entrepreneurs"}, {"id": "a5fd0cda-3211-4a19-afd7-0e81a924f037", "type": "concept", "title": "Uneven industrialization across Europe"}], "description": "Industrialization reorganized energy, labor, production, time, and global markets."}, {"id": "ea7485f6-e4d4-40c6-801e-e4212cade074", "type": "subtopic", "title": "Urban life and social change", "children": [{"id": "1f135414-52e4-41fe-8846-bbc1a9c80a21", "type": "concept", "title": "Urban crowding and sanitation"}, {"id": "adbd0532-faca-45b8-890a-8e772f538981", "type": "concept", "title": "Class formation"}, {"id": "78bdfea7-e6df-4ce3-a087-a242c05556ad", "type": "concept", "title": "Family economies and child labor"}, {"id": "9c00e0f5-09d9-420f-9d94-af59ec6944d1", "type": "concept", "title": "Public health and housing reform"}], "description": "Cities became laboratories of modern inequality, public health, policing, culture, and reform."}, {"id": "6240a652-8fe7-47da-a6cc-96859e94bce7", "type": "subtopic", "title": "Labor politics and social reform", "children": [{"id": "7943a0d3-aa47-46f9-8732-27667348cd89", "type": "concept", "title": "Trade unions"}, {"id": "81966d10-5de4-4ea0-a526-ce29fc741044", "type": "concept", "title": "Chartism and reform movements"}, {"id": "c83bbc0f-af11-4127-9d06-63053f5ebacb", "type": "concept", "title": "Marx and socialism"}, {"id": "81af75c9-2f7e-406b-a8b2-202ff719b1f1", "type": "concept", "title": "Cooperatives, mutual aid, and welfare beginnings"}], "description": "The social question made poverty, work, rights, welfare, and class conflict central to modern politics."}]}, {"id": "c6b927e5-1b07-40bd-ade6-2fb844225139", "type": "topic", "title": "Nationalism, Liberalism, Conservatism, Socialism, and Imperialism", "description": "Track nineteenth-century ideologies, nation-making, imperial expansion, mass politics, and contested visions of modern society.", "children": [{"id": "f372fbbb-cc97-4482-bdca-b573aa2862c0", "type": "subtopic", "title": "Ideologies after 1815", "children": [{"id": "61f69679-d89e-474d-941c-23e097fe3133", "type": "concept", "title": "Liberal constitutionalism"}, {"id": "89fece4d-c542-49ca-a3c0-d6a1506e3dce", "type": "concept", "title": "Conservatism and order"}, {"id": "66458f74-d996-4c3c-a306-f165af0c118c", "type": "concept", "title": "Romantic nationalism"}, {"id": "d67d0b51-6331-48eb-9675-e45c108575de", "type": "concept", "title": "Socialism and anarchism"}], "description": "Students learn the political languages that shaped nineteenth-century revolutions, reforms, and state-building."}, {"id": "75cd9dd3-aa87-4ce8-baa3-1140ce2fc806", "type": "subtopic", "title": "Nation-making and empire inside Europe", "children": [{"id": "af4ec96c-cf59-4295-8efe-2353b77f4f5d", "type": "concept", "title": "Italian unification"}, {"id": "45c7fe95-7500-4943-8c2f-7e8c521bf350", "type": "concept", "title": "German unification"}, {"id": "3e31bce4-77cf-4265-b609-90aa4c3039f1", "type": "concept", "title": "Habsburg and Ottoman pluralism"}, {"id": "c2752bd6-17f6-4894-b62a-91b8d268635a", "type": "concept", "title": "Minorities, citizenship, and borderlands"}], "description": "National states were built through war, schooling, language policy, bureaucracy, and exclusion."}, {"id": "99b98c4b-341f-4ea1-8c8e-366b49db958b", "type": "subtopic", "title": "European imperialism and global power", "children": [{"id": "191914a2-dd8e-4228-a59d-8aa0acfc1527", "type": "concept", "title": "Scramble for Africa"}, {"id": "e7088e20-af5c-440c-80cf-f21ecb08c478", "type": "concept", "title": "Orientalism and race science"}, {"id": "cceaff90-0171-4b1e-a43b-8f9f51263bbc", "type": "concept", "title": "Missionaries and colonial knowledge"}, {"id": "6558d532-b3f8-49f7-8dd6-f96c69d086de", "type": "concept", "title": "Anti-imperial critique"}], "description": "The survey connects Europe's domestic transformation to overseas conquest, racial ideology, and global capitalism."}]}, {"id": "f913cdcf-f3cc-46de-a2df-4424f03c4e8c", "type": "topic", "title": "Modern Culture, Gender, Science, and Fin-de-Siecle Europe", "description": "Explore cultural modernity, gender politics, secularization, scientific authority, antisemitism, and anxieties before 1914.", "children": [{"id": "4633becc-390c-4836-a5f7-fd4b4e3a4291", "type": "subtopic", "title": "Mass culture and modernism", "children": [{"id": "128ac8e3-890c-4f55-a18e-4463e30c15ab", "type": "concept", "title": "Mass literacy and press"}, {"id": "fe4c7d47-2ca9-4f31-a97f-86ff00695b1b", "type": "concept", "title": "Impressionism and modernism"}, {"id": "f58202a4-601f-4c9e-b549-bfdaa63f083c", "type": "concept", "title": "Leisure, tourism, and sport"}, {"id": "d058e1e7-ba92-4970-843d-27e7db65fb17", "type": "concept", "title": "Department stores and consumer culture"}], "description": "Students explore how newspapers, consumer culture, museums, cinema, sport, and art changed European identities."}, {"id": "c3b038f2-cb3f-4e04-a190-853fbf160606", "type": "subtopic", "title": "Gender, sexuality, and the family", "children": [{"id": "39a4cffa-9738-4b28-809d-5afef7c1328b", "type": "concept", "title": "First-wave feminism"}, {"id": "8b41cf05-9d53-49ad-8a55-ebf78addf3a0", "type": "concept", "title": "Marriage and property rights"}, {"id": "9f3ef0c4-02a3-4979-9a89-87127f2f5447", "type": "concept", "title": "Sexology and moral regulation"}, {"id": "8137c79b-92d5-47cc-a420-7bc315a6f054", "type": "concept", "title": "Masculinity, militarism, and family ideals"}], "description": "Modern Europe remade private life through feminism, demographic change, medical authority, and legal reform."}, {"id": "6368fc11-b173-46e0-a62e-b07a7c8a827a", "type": "subtopic", "title": "Science, secularization, and anxiety", "children": [{"id": "d4edb9ca-8457-4b24-bd83-f4c13f6e8f39", "type": "concept", "title": "Darwinism and social Darwinism"}, {"id": "6dc137b1-1a8c-496e-bd39-406a22e0e090", "type": "concept", "title": "Psychology and the unconscious"}, {"id": "ca7f6837-85f2-4fb5-be40-930f9517f913", "type": "concept", "title": "Antisemitism and racial thought"}, {"id": "f34a17a9-5762-48d9-870a-c2ffde56fbd9", "type": "concept", "title": "Secularization and religious revival"}], "description": "Scientific authority produced confidence and unease, especially around race, heredity, psychology, and social order."}]}, {"id": "7615fb12-5ef0-4f0e-8903-d1e7e3a1c5c4", "type": "topic", "title": "World War I, Russian Revolution, and Interwar Crisis", "description": "Study total war, revolution, collapse of empires, new states, economic crisis, democracy under pressure, and radical politics.", "children": [{"id": "1d1234d7-65a0-452b-9cab-0ed6822704d4", "type": "subtopic", "title": "World War I as total war", "children": [{"id": "48c9f421-15b6-47fd-a931-9261b7d94d93", "type": "concept", "title": "Alliance systems and July Crisis"}, {"id": "03a521b6-7762-4936-a4b2-47049a0cffd4", "type": "concept", "title": "Trench warfare and home fronts"}, {"id": "8fac4d26-9bf6-4c48-a2aa-c0d9e4a45631", "type": "concept", "title": "Colonial troops and global war"}, {"id": "8e11337c-6fd9-4ede-9a04-3a62eec4d1a4", "type": "concept", "title": "War trauma and commemoration"}], "description": "The war transformed states, economies, gender roles, empires, and everyday life."}, {"id": "61a4db21-b3e8-463b-9876-3e0a40afe2ee", "type": "subtopic", "title": "Revolution and the collapse of empires", "children": [{"id": "c946f287-654c-4908-a966-67e40c598c2b", "type": "concept", "title": "Russian Revolutions of 1917"}, {"id": "868b63b2-43e1-4925-b77e-0a58b430eaed", "type": "concept", "title": "Treaty of Versailles"}, {"id": "a28f0ae7-0e1e-4f3a-a1a2-6f7e219bd73d", "type": "concept", "title": "Ottoman, Habsburg, Romanov, and German collapse"}, {"id": "5a6edea8-ff9f-4296-a037-2d7f91b94209", "type": "concept", "title": "New states and minority problems"}], "description": "Students connect military defeat, social crisis, ideology, and national self-determination."}, {"id": "d3cb537c-2a99-4825-af57-6aaa2e4c212e", "type": "subtopic", "title": "Interwar democracy and crisis", "children": [{"id": "217a86d5-e2c3-40b0-a8b8-05ff7f499726", "type": "concept", "title": "Weimar Republic"}, {"id": "23fb234a-1e3c-4322-95b7-208937b1e516", "type": "concept", "title": "Great Depression"}, {"id": "abe620dc-90de-4113-87d6-9438582bb73d", "type": "concept", "title": "Popular fronts and authoritarianism"}, {"id": "48091e7e-8c27-474c-ab65-22fc89b73ea2", "type": "concept", "title": "Appeasement and collective security failure"}], "description": "The interwar period reveals how fragile democracy became amid economic instability, social fear, and ideological polarization."}]}, {"id": "001ec7f9-50ae-46ae-a281-68aa9eb885b4", "type": "topic", "title": "Fascism, Nazism, World War II, Genocide, and the Holocaust", "description": "Analyze fascist and Nazi movements, occupation, collaboration, resistance, genocide, and the moral rupture of the Holocaust.", "children": [{"id": "174a0717-4ecc-443e-a7cc-78da1da534ff", "type": "subtopic", "title": "Fascism and Nazism", "children": [{"id": "a9b6a5ec-6194-453a-993c-4e6b58a8bb50", "type": "concept", "title": "Mussolini and Italian fascism"}, {"id": "062ceaa4-3f1f-43db-b0e4-fe24079a04b7", "type": "concept", "title": "Hitler and National Socialism"}, {"id": "211f0879-5d76-4da8-9fa3-f6d61fd2d642", "type": "concept", "title": "Propaganda and paramilitary politics"}, {"id": "b788953c-73c4-4fc4-8bb3-68d9b5c16c90", "type": "concept", "title": "Race, eugenics, and Volksgemeinschaft"}], "description": "Students analyze fascism as a modern mass politics of violence, nation, hierarchy, spectacle, and anti-liberalism."}, {"id": "0cf7a376-3cb4-4632-ab43-973c28f4d4e4", "type": "subtopic", "title": "World War II and occupation", "children": [{"id": "39213d4c-f2eb-471d-a53e-79a25796f412", "type": "concept", "title": "Blitzkrieg and total war"}, {"id": "63aa0e40-489b-4a7e-9270-a9ab8049a851", "type": "concept", "title": "Occupation regimes"}, {"id": "4825c2c1-e44f-4328-b585-e56fabbb07c2", "type": "concept", "title": "Resistance and collaboration"}, {"id": "68fea3f8-aa05-43f9-9c75-a7259b6d11ec", "type": "concept", "title": "Eastern Front and war of annihilation"}], "description": "The war is treated as a European and global conflict involving occupation, resistance, collaboration, and civilian suffering."}, {"id": "4b3c58dc-5cc9-4456-9cbc-175a35b9dd54", "type": "subtopic", "title": "Holocaust and genocide", "children": [{"id": "dbfdf77f-e1d5-4728-9472-578b53d0fdda", "type": "concept", "title": "Antisemitism and racial state"}, {"id": "630b4520-156d-48b2-abd3-79b7a3dcf5b3", "type": "concept", "title": "Ghettos, shootings, camps, and extermination centers"}, {"id": "65bc7c1a-00f2-49f9-85ac-8dab3df9b932", "type": "concept", "title": "Roma, disabled, Polish, Soviet, queer, and other victims"}, {"id": "254db69f-aa6d-46fe-a5d0-0884692b31cb", "type": "concept", "title": "Justice, testimony, and Holocaust memory"}], "description": "The Holocaust requires careful study of ideology, bureaucracy, war, collaboration, victims' experiences, and memory."}]}, {"id": "88c9e0f8-eb52-485e-b3df-37615fa6c8ac", "type": "topic", "title": "Cold War Europe: Reconstruction, Welfare States, Integration, and Decolonization", "description": "Examine Europe's division, recovery, social democracy, Soviet bloc life, European integration, migration, and the end of overseas empires.", "children": [{"id": "c1247c23-d30a-4000-8257-cbbeb6afdb4a", "type": "subtopic", "title": "Reconstruction and divided Europe", "children": [{"id": "8878e5f0-7a69-4f4e-8e6f-e56061d7bedf", "type": "concept", "title": "Marshall Plan"}, {"id": "4b9e9990-2735-4720-bf9d-1d90a7151fe0", "type": "concept", "title": "NATO and Warsaw Pact"}, {"id": "53cb450b-73bf-44ef-b166-98bc5f70a833", "type": "concept", "title": "German division"}, {"id": "a894d435-9bd4-49ee-98dc-f5b778306c2a", "type": "concept", "title": "Postwar welfare states and social democracy"}], "description": "Students study how Europe rebuilt under American and Soviet power while creating new political and social settlements."}, {"id": "4df5235f-fcb9-4fa0-a991-2f2d24a30eb2", "type": "subtopic", "title": "Soviet bloc and Western Europe", "children": [{"id": "3181635a-24ea-4788-beac-0778abb6ad3c", "type": "concept", "title": "Stalinism and de-Stalinization"}, {"id": "3a09e828-7c14-431d-8d69-0e2ea0d3dcd8", "type": "concept", "title": "1956 Hungary and 1968 Prague Spring"}, {"id": "dbea86ef-8e9f-41b3-86f9-61e8b3c39fd7", "type": "concept", "title": "1968 protest movements"}, {"id": "c20281e6-2849-4510-a621-cc5df769c2e5", "type": "concept", "title": "Everyday life, youth culture, and consumerism"}], "description": "Cold War Europe included different forms of prosperity, repression, reform, dissent, and consumer culture."}, {"id": "5ed6c55b-517f-475a-9bb4-dbeacb9797dd", "type": "subtopic", "title": "Integration, decolonization, and migration", "children": [{"id": "e61ea788-4115-4da4-98a6-aa11e4928482", "type": "concept", "title": "European Coal and Steel Community to European Community"}, {"id": "2f7d5e13-8138-4150-9949-ab68cb1d4c97", "type": "concept", "title": "Algeria and French decolonization"}, {"id": "65b35d7e-8731-4f90-bc33-bf459dbe4d14", "type": "concept", "title": "Britain and post-imperial migration"}, {"id": "1d9e6424-9200-4994-908c-8c3edb201b01", "type": "concept", "title": "Guest workers and multicultural Europe"}], "description": "European integration and decolonization must be studied together, since postwar Europe was remade by empire's end and migration."}]}, {"id": "2a58532e-e712-4ba6-ab59-25855dddb474", "type": "topic", "title": "Europe since 1989: Union, Migration, Memory, Democracy, and War", "description": "Bring the survey to the present through post-communist transitions, EU expansion, memory politics, migration, populism, and conflict on Europe's borders.", "children": [{"id": "8d1d89cb-2a99-4b03-b1d4-3dee5a548307", "type": "subtopic", "title": "End of the Cold War and post-communist transitions", "children": [{"id": "262fc5fb-d6d6-4c0b-baee-cfec9744f3cf", "type": "concept", "title": "1989 revolutions"}, {"id": "2a08e248-3602-434b-b37b-12c345684e6b", "type": "concept", "title": "German reunification"}, {"id": "514c0a5d-468a-45fe-92d7-ac206efed2cb", "type": "concept", "title": "Shock therapy and privatization"}, {"id": "ed57890a-b46d-4c98-b831-68f667125def", "type": "concept", "title": "Yugoslav wars and ethnic violence"}], "description": "Students examine the collapse of communist regimes and the uneven making of post-1989 political economies."}, {"id": "8fc66d34-8777-466e-8540-d388427ce024", "type": "subtopic", "title": "European Union and contested sovereignty", "children": [{"id": "e7e7b8a2-6cea-4d4b-a373-d01f7d6fc123", "type": "concept", "title": "Maastricht Treaty and euro"}, {"id": "f25ed638-e20b-4084-847f-fecc35aeccbb", "type": "concept", "title": "EU enlargement"}, {"id": "ae900c82-eaa4-41aa-ab76-b4069cf5c99d", "type": "concept", "title": "Brexit"}, {"id": "a4c2d33b-62a3-44da-8c2c-68ad223096dd", "type": "concept", "title": "Eurozone and legitimacy crises"}], "description": "The EU is studied as a historical experiment in integration, law, currency, borders, and democratic legitimacy."}, {"id": "64d89565-1379-4711-b199-4837d6d39beb", "type": "subtopic", "title": "Memory, migration, and democracy under strain", "children": [{"id": "cfa6bf1c-965f-46b2-b685-191e272eb5e8", "type": "concept", "title": "Holocaust and colonial memory"}, {"id": "767802ac-d557-4ff4-98a7-57b8b8ea84d7", "type": "concept", "title": "Refugees and migration politics"}, {"id": "4fd3c9c7-b69b-49ff-b593-491119ec44fd", "type": "concept", "title": "Populism and democratic backsliding"}, {"id": "5e3b0285-acdb-435f-a13d-88b1d133e4fc", "type": "concept", "title": "Russia's 2022 invasion of Ukraine and European security"}], "description": "The final unit connects historical memory to present debates over migration, populism, war, race, and European identity."}]}], "dbBacked": true}$eursjson$::jsonb,
  true,
  false,
  'course',
  'public'
where not exists (
  select 1 from public.learning_paths where slug = 'european-history-survey'
);

update public.learning_paths
set
  title = 'European History (Survey)',
  goal = 'European History (Survey)',
  summary = 'A survey of European history from antiquity and the Middle Ages to the post-1989 era. Students interpret primary sources, connect political, social, cultural, economic, religious, gender, imperial, and intellectual history in one timeline, compare western, eastern, northern, southern, and borderland experiences, and analyze how Europe shaped and was shaped by global exchange, empire, migration, war, and decolonization.',
  data = $eursjson${"slug": "european-history-survey", "title": "European History (Survey)", "description": "A survey of European history from antiquity and the Middle Ages to the post-1989 era. Students interpret primary sources, connect political, social, cultural, economic, religious, gender, imperial, and intellectual history in one timeline, compare western, eastern, northern, southern, and borderland experiences, and analyze how Europe shaped and was shaped by global exchange, empire, migration, war, and decolonization.", "topics": [{"id": "a89291e3-8b1d-4d14-8808-15738df1b881", "type": "topic", "title": "Historical Method, Geography, and Periodization", "description": "Frame Europe as a changing historical category and learn how historians build arguments from sources, chronology, geography, and interpretation.", "children": [{"id": "d969d164-adc2-4435-9999-f4cba8a604f8", "type": "subtopic", "title": "Europe as a historical category", "children": [{"id": "9bab3c7b-7b0e-4776-9d19-8cc42ac5b841", "type": "concept", "title": "Geographic Europe and cultural Europe"}, {"id": "1eaead6c-eb91-478c-8fe3-3d3b7559f612", "type": "concept", "title": "Mediterranean, Atlantic, Baltic, and Eurasian frames"}, {"id": "f6349f7a-6fae-49b8-ace0-f2dc8e7e0bec", "type": "concept", "title": "Center, periphery, and borderlands"}, {"id": "ac163709-c5b7-4919-9f8c-ffa872ffdbfb", "type": "concept", "title": "Europe in world history rather than Europe alone"}], "description": "Students begin by questioning what Europe is, where its borders are drawn, and why those answers change over time."}, {"id": "e440ccac-2838-464f-9823-9a2b25006053", "type": "subtopic", "title": "Sources and historical interpretation", "children": [{"id": "09f77d89-200a-417f-9574-956e365f6d88", "type": "concept", "title": "Primary and secondary sources"}, {"id": "81117aaa-e034-4728-a21e-10cdef2d10db", "type": "concept", "title": "Chronology and causation"}, {"id": "8e8a4be6-99dc-42ab-a3f7-f8d2123c4882", "type": "concept", "title": "Bias, silence, and perspective"}, {"id": "046feda9-27cd-462d-9673-8180592decb4", "type": "concept", "title": "Historiography and competing interpretations"}], "description": "Survey history becomes richer when students learn how evidence is made, preserved, translated, and argued over."}, {"id": "47b252c4-aec2-465f-ae42-c8102da6748b", "type": "subtopic", "title": "Periodization and scale", "children": [{"id": "cba12a71-eb43-4e1f-b34b-69ce1633164e", "type": "concept", "title": "Ancient, medieval, early modern, modern, and contemporary"}, {"id": "026c1b75-8bf8-43bf-8cd4-ff7f7ad978f8", "type": "concept", "title": "Local, regional, national, imperial, and global scales"}, {"id": "e8ab5ed7-927f-4b69-8c7a-44efd4916dbd", "type": "concept", "title": "Continuity and change"}, {"id": "1667dfc8-421b-469b-bcf7-886282ad70c7", "type": "concept", "title": "Survey maps, timelines, and comparative cases"}], "description": "Periods are tools, not facts; students learn when labels like medieval, early modern, and modern clarify or distort the past."}]}, {"id": "261ca472-876b-4c83-b6c4-5878d40c862f", "type": "topic", "title": "Classical, Late Antique, and Christian Foundations", "description": "Trace Greek, Roman, Jewish, Christian, and late antique inheritances that shaped later European institutions, identities, and debates.", "children": [{"id": "b96ab614-a5e4-4786-9b6a-e7e5cc851a87", "type": "subtopic", "title": "Greek and Roman political inheritances", "children": [{"id": "e7081f31-703e-46e6-bf95-f1e1beee1608", "type": "concept", "title": "Athenian democracy and citizenship"}, {"id": "f789eca6-08ce-4fc1-ad55-867e3e843b08", "type": "concept", "title": "Roman republic and empire"}, {"id": "2f55c616-49c1-44c1-9907-f25ab641633b", "type": "concept", "title": "Law, citizenship, and administration"}, {"id": "8629dd0a-fbcc-4d1e-80d9-d03d64dd9483", "type": "concept", "title": "Classical memory in later Europe"}], "description": "This subtopic introduces political forms and civic languages later Europeans repeatedly revived, contested, and reinvented."}, {"id": "56e29d8f-40d3-4124-82e0-fbaa89f92e05", "type": "subtopic", "title": "Late antiquity and transformation", "children": [{"id": "7f816ff3-80a9-4bfe-a18e-29d816169400", "type": "concept", "title": "Imperial crisis and reform"}, {"id": "7b93a6b0-787a-413a-bde7-c1d968aaacc8", "type": "concept", "title": "Germanic kingdoms"}, {"id": "6221fe68-c9d2-4aba-ac2d-754b9bfd7f7f", "type": "concept", "title": "Continuity of Roman law and cities"}, {"id": "135d9d4f-1b63-4ce6-b2ac-0c173c319f80", "type": "concept", "title": "Migration, settlement, and cultural blending"}], "description": "Late antiquity shows that Rome did not simply fall; institutions, religions, economies, and identities were transformed over centuries."}, {"id": "86231387-b096-44b1-9537-e0c78ebbad3f", "type": "subtopic", "title": "Christianity and religious authority", "children": [{"id": "c5422582-6709-49ed-9049-b442ff039ec3", "type": "concept", "title": "Church hierarchy and councils"}, {"id": "430bad4d-b7af-42a6-be0a-2a6a4a686914", "type": "concept", "title": "Monasticism"}, {"id": "f42d3ee8-261b-4ea2-9bac-ddd30b8fa727", "type": "concept", "title": "Augustine and Christian political thought"}, {"id": "eed7ddb6-cb68-44ff-9b5d-b3bd8ab4f02a", "type": "concept", "title": "Judaism, Christianity, and religious minorities"}], "description": "Christian institutions became major forces in education, welfare, law, kingship, art, and conflict."}]}, {"id": "d44985a8-a0db-48b8-bcd1-cf73f46264b3", "type": "topic", "title": "Early Medieval Europe, Byzantium, Islam, and Post-Roman Worlds", "description": "Study political fragmentation, religious expansion, cultural exchange, and the making of medieval societies after Rome.", "children": [{"id": "fda26036-2737-45db-be6b-b79021554a46", "type": "subtopic", "title": "Post-Roman kingdoms and Carolingian Europe", "children": [{"id": "76ce2dfb-8c96-4661-8d42-80d300c40274", "type": "concept", "title": "Frankish expansion"}, {"id": "9b09e0d6-fe03-4a76-accf-115e1408e4de", "type": "concept", "title": "Carolingian renaissance"}, {"id": "ba289187-ecb6-4ccc-8900-2ce864a864bc", "type": "concept", "title": "Manorialism and local lordship"}, {"id": "a49638f9-1e1d-4416-9103-2328738aeb4a", "type": "concept", "title": "Kingship, oath, and loyalty"}], "description": "Students examine how new kingdoms created authority from Roman, Christian, Germanic, and local traditions."}, {"id": "89e20be7-0ad3-4f42-aaa7-0b82aeef862c", "type": "subtopic", "title": "Byzantium and eastern Christianity", "children": [{"id": "1a11d2fa-18e0-4e14-a1e5-b0f044b97fcc", "type": "concept", "title": "Constantinople and imperial government"}, {"id": "f0049041-6ed1-482d-a247-84b3afa94e90", "type": "concept", "title": "Orthodox Christianity"}, {"id": "74d7c762-c458-4d80-ba89-aacd05a1c07a", "type": "concept", "title": "Iconoclasm and church-state relations"}, {"id": "cfa44a89-42b2-41d2-befe-c17b31675234", "type": "concept", "title": "Diplomacy with Slavs, Arabs, and Latins"}], "description": "Byzantium keeps eastern Europe and the Mediterranean in the survey, complicating a western-only story of Europe."}, {"id": "503a14d5-daa8-444d-99d3-5a4a1f4a9c95", "type": "subtopic", "title": "Islamic worlds and European exchange", "children": [{"id": "ce838724-9cf0-4759-b320-dd0eebcae1b5", "type": "concept", "title": "Al-Andalus and Sicily"}, {"id": "c21e5bcc-22d6-412e-aadf-c8a6d195a2ab", "type": "concept", "title": "Mediterranean trade"}, {"id": "29d51231-680a-4b54-a6b5-544af7158a02", "type": "concept", "title": "Translation movements"}, {"id": "8d6ab4e1-7173-468e-b6a5-c42ba6c40ff3", "type": "concept", "title": "Jewish, Christian, and Muslim coexistence and conflict"}], "description": "Islamic expansion connected Europe to wider Afro-Eurasian worlds through conflict, trade, science, translation, and coexistence."}]}, {"id": "aa17796c-0870-4635-9efd-d3834f40e93b", "type": "topic", "title": "High Medieval Europe: Lordship, Cities, Universities, and Crusades", "description": "Analyze the growth of feudal, urban, ecclesiastical, commercial, and intellectual institutions from roughly 1000 to 1300.", "children": [{"id": "099fb239-4388-40ac-b997-8662e3e8e728", "type": "subtopic", "title": "Lordship, peasants, and medieval society", "children": [{"id": "b57469d6-6024-44db-aa9a-66853e1e23c7", "type": "concept", "title": "Feudal relationships"}, {"id": "5586a6e8-11ba-4471-9ea9-633868e1e058", "type": "concept", "title": "Manors and peasant obligations"}, {"id": "458178d9-8298-41fc-84de-d3192537d1cf", "type": "concept", "title": "Nobility and chivalry"}, {"id": "e2e50f05-8893-46a9-b7f2-f8f8a0ae53f3", "type": "concept", "title": "Village life and customary rights"}], "description": "This subtopic explains how power and production worked in a mostly agrarian world."}, {"id": "6a40b52c-d892-437b-b45a-f80ab0056a10", "type": "subtopic", "title": "Urban revival, commerce, and universities", "children": [{"id": "f8ed783d-007b-4b6e-a20c-d8da970ce74f", "type": "concept", "title": "Guilds and merchant networks"}, {"id": "cb8057d4-07a2-4d07-bb57-78957c407bd1", "type": "concept", "title": "Italian city-states and the Hanseatic League"}, {"id": "17212f87-c73a-420c-a68b-492f4c21c941", "type": "concept", "title": "Universities and scholasticism"}, {"id": "59ed2edc-310f-48e9-a9f8-b91d45af0945", "type": "concept", "title": "Canon law and professional learning"}], "description": "Students see medieval Europe as dynamic, commercial, literate, and institutionally creative."}, {"id": "d9d7d67f-9537-400f-9e3c-b0524240dbba", "type": "subtopic", "title": "Church reform and crusading", "children": [{"id": "010b0d52-6110-4ae7-8efd-463bf0d57a43", "type": "concept", "title": "Gregorian reform"}, {"id": "3dbbb4e5-04e1-4d70-b421-5e9fcef5d873", "type": "concept", "title": "Pilgrimage and holy war"}, {"id": "9f34e85c-f4d3-4ad1-b50f-466ae4d87559", "type": "concept", "title": "Crusader states"}, {"id": "1bf24147-4da0-4983-a284-29dd612a9f34", "type": "concept", "title": "Persecution of Jews, heretics, and religious others"}], "description": "The crusades reveal how piety, violence, papal authority, colonization, and cross-cultural contact could merge."}]}, {"id": "512e5f64-87b1-463f-827e-b454e7bd47ab", "type": "topic", "title": "Late Medieval Crisis, Renaissance, and Humanism", "description": "Connect plague, war, social conflict, state consolidation, urban culture, art, and humanist learning in the transition to early modern Europe.", "children": [{"id": "f713efe6-3f40-4a9d-8096-e6aedb415cb6", "type": "subtopic", "title": "Plague, war, and social disruption", "children": [{"id": "b71c7abd-67d1-401d-80d1-42b72b9a9444", "type": "concept", "title": "Black Death"}, {"id": "2728e47b-354c-4a00-9b27-2447961b13de", "type": "concept", "title": "Hundred Years' War"}, {"id": "d9e17649-1b42-4f8d-b763-9e13a02841c1", "type": "concept", "title": "Peasant revolts and labor scarcity"}, {"id": "b6ee93a4-d07e-4149-b34b-2a00f877f552", "type": "concept", "title": "Crisis of church authority"}], "description": "The fourteenth century teaches students how demographic shock can transform labor, power, belief, and social conflict."}, {"id": "8b03c5fe-2d96-47e0-9ba2-b20d9cd150d7", "type": "subtopic", "title": "Renaissance culture and humanism", "children": [{"id": "0e2dba97-e28f-4ddc-9565-4c32fe898185", "type": "concept", "title": "Classical revival"}, {"id": "f3104078-16b3-4d68-9793-3e765f5176c6", "type": "concept", "title": "Civic humanism"}, {"id": "2bdc369f-3aa3-401a-a98b-62b3d1ef06b1", "type": "concept", "title": "Patronage and art"}, {"id": "f50e7a88-7514-41b5-aeb8-d116cded6d57", "type": "concept", "title": "Printing and manuscript cultures"}], "description": "The Renaissance is treated not as a miracle but as an urban, textual, artistic, political, and social movement."}, {"id": "fe7734f8-64c2-4a84-ab01-04a6bfa4964c", "type": "subtopic", "title": "State consolidation and political thought", "children": [{"id": "59ddacde-4d02-4bb8-abdf-bc57a5994e2f", "type": "concept", "title": "New monarchies"}, {"id": "ac92d093-9024-46d8-85be-38850da775ec", "type": "concept", "title": "Italian diplomacy"}, {"id": "416036b9-e9da-46d3-9c2f-dd54b06b083f", "type": "concept", "title": "Machiavelli and reason of state"}, {"id": "7eed4540-f4e9-45b5-b648-4dac3295bc50", "type": "concept", "title": "Courts, cities, and republics"}], "description": "Late medieval and Renaissance politics show the growth of taxation, diplomacy, bureaucracy, and realistic analysis of power."}]}, {"id": "791cf615-d0fb-4465-a980-b7665ca1b21f", "type": "topic", "title": "Reformation, Confessional Europe, and Wars of Religion", "description": "Understand how religious reform and confessional conflict transformed politics, culture, literacy, family life, and state power.", "children": [{"id": "2a8b1209-8374-4dad-a633-aec2a1404d09", "type": "subtopic", "title": "Protestant and Catholic reform", "children": [{"id": "f89937b0-294f-4633-aa23-c6e0d28ead31", "type": "concept", "title": "Luther, Calvin, and radical reform"}, {"id": "bb714688-854f-41f6-9042-81c7b4e5addd", "type": "concept", "title": "Catholic reform and Council of Trent"}, {"id": "5119d04b-305d-4cc9-b466-172fcda0cfc3", "type": "concept", "title": "Bible translation and print"}, {"id": "0b023f6f-225e-4468-913c-89401d80118d", "type": "concept", "title": "Education, discipline, and moral reform"}], "description": "Students learn how theological disputes became social, political, and cultural transformations."}, {"id": "2476fe0a-f0ed-48cd-b622-763e0060ef38", "type": "subtopic", "title": "Confessional states and everyday religion", "children": [{"id": "d8ef6cad-5b7a-467b-8aad-1346d37a3636", "type": "concept", "title": "Parish life and ritual"}, {"id": "bc02cee7-2760-4cbb-99c3-8db31bf2bfd0", "type": "concept", "title": "Marriage and household discipline"}, {"id": "1713462a-630d-4b7c-998f-08632a93adf9", "type": "concept", "title": "Witch hunts and popular belief"}, {"id": "224de0a8-f6bd-48a7-a11a-153db16717c6", "type": "concept", "title": "Religious minorities and toleration"}], "description": "Confessionalization shows how churches and states tried to shape belief, behavior, family, and community."}, {"id": "267d2bd1-20be-496d-9964-abb76bf6c717", "type": "subtopic", "title": "Wars of religion and settlement", "children": [{"id": "bf58fb9c-33a4-4fc1-9db5-7d5dec338448", "type": "concept", "title": "French Wars of Religion"}, {"id": "725fc82e-05f2-4c43-b626-adad44bcbfdf", "type": "concept", "title": "Dutch Revolt"}, {"id": "ed60f024-e718-4a75-983c-37ad86f87a79", "type": "concept", "title": "Thirty Years' War"}, {"id": "88d4ab1d-a05e-40ea-af7b-be69521530a2", "type": "concept", "title": "Peace of Westphalia"}], "description": "Religious conflict reorganized sovereignty and forced Europeans to rethink coexistence, authority, and violence."}]}, {"id": "c8feea3f-d94b-4e6c-b088-0f629c6fda27", "type": "topic", "title": "State Formation, Absolutism, Constitutionalism, and the Scientific Revolution", "description": "Compare early modern state power, constitutional conflict, global competition, and new ways of knowing nature and society.", "children": [{"id": "b0075a08-155d-48e0-bbb8-e6c3df059743", "type": "subtopic", "title": "Absolutism and fiscal-military states", "children": [{"id": "77dce281-5d77-47ab-8610-d4bb377a7463", "type": "concept", "title": "Louis XIV and Versailles"}, {"id": "3d91fe59-54e0-4e54-ac40-2da5636e7eb4", "type": "concept", "title": "Standing armies"}, {"id": "3941f691-f27d-4b9e-a223-1803f7b67c38", "type": "concept", "title": "Taxation and administration"}, {"id": "1c3bada9-85cb-496d-a782-8fd443f8df7a", "type": "concept", "title": "Mercantilism and empire"}], "description": "Students study how war, taxation, bureaucracy, and court culture expanded state power."}, {"id": "2ad75b3a-2baa-4a31-8432-7bea40340854", "type": "subtopic", "title": "Constitutional conflict and political rights", "children": [{"id": "01a9b6fd-9b71-44d9-87ec-a25b1c2d0dac", "type": "concept", "title": "English Civil Wars"}, {"id": "87c6da6a-595a-440f-8cf9-182d566ffca9", "type": "concept", "title": "Glorious Revolution"}, {"id": "fcae53b1-3656-4084-a8ba-c5ef7c3a3a4d", "type": "concept", "title": "Parliament and rights"}, {"id": "db724a39-b508-426a-9327-61ad8c3a6088", "type": "concept", "title": "Republicanism and mixed government"}], "description": "England, the Dutch Republic, and other cases reveal alternative paths to political authority."}, {"id": "5420eebb-2f0a-4284-9d00-7c6b196af2e9", "type": "subtopic", "title": "Scientific Revolution and knowledge", "children": [{"id": "d9ff6150-2c60-4656-a46a-8ffb8d8267dd", "type": "concept", "title": "Copernicus, Galileo, Newton, and Bacon"}, {"id": "4c118a86-8299-4a04-9552-3ded79e52e3b", "type": "concept", "title": "Scientific societies"}, {"id": "e6352035-4d0b-46b5-b18d-3fe32651e3f3", "type": "concept", "title": "Mechanism and experiment"}, {"id": "039c77f9-166e-41ce-9eca-9ce92811eff4", "type": "concept", "title": "Science, religion, and empire"}], "description": "New methods of observing nature transformed authority, technology, religion, and ideas of progress."}]}, {"id": "276d100d-6023-45d2-b422-c2bea55defa8", "type": "topic", "title": "Enlightenment, Atlantic Revolutions, and Napoleon", "description": "Assess how ideas of reason, rights, sovereignty, citizenship, race, empire, and revolution reshaped Europe and the Atlantic world.", "children": [{"id": "f00dd008-5420-44d2-867d-cde3e0da4d19", "type": "subtopic", "title": "Enlightenment thought and public culture", "children": [{"id": "8810ed79-19ff-4e98-a1f6-b0f0744bb722", "type": "concept", "title": "Salons, coffeehouses, and academies"}, {"id": "d5b2689c-6fa7-4c64-8dfc-09ea05676ddd", "type": "concept", "title": "Voltaire, Rousseau, Diderot, and Kant"}, {"id": "b0a1de69-8467-400d-ac5f-8e0ad01863db", "type": "concept", "title": "Natural rights and political economy"}, {"id": "fab812e8-7f36-4b7f-8366-a7a42dc451e9", "type": "concept", "title": "Limits of Enlightenment: gender, race, and empire"}], "description": "The Enlightenment introduces students to critique, sociability, print, reform, and debates over universal reason."}, {"id": "29e6f8a5-9841-462d-b79a-7e22ace0a222", "type": "subtopic", "title": "Revolutionary politics", "children": [{"id": "0a97de6f-00d3-4ca6-ad77-799df394ca9a", "type": "concept", "title": "American and French revolutionary contexts"}, {"id": "03ffaca5-df0b-41bc-91a0-b1e91d62c02e", "type": "concept", "title": "1789 and rights declarations"}, {"id": "e7e45da5-fdc0-43c1-ad1d-97e2f6c7454e", "type": "concept", "title": "Republicanism and terror"}, {"id": "1708362c-6e0b-498f-b329-85bee2681696", "type": "concept", "title": "Haitian Revolution and Atlantic slavery"}], "description": "Students compare how sovereignty shifted from monarchs to nations, citizens, constitutions, and armies."}, {"id": "849e0b6b-b7b3-41cc-b027-1b0e4af7613f", "type": "subtopic", "title": "Napoleonic Europe", "children": [{"id": "4d0c8157-2c67-416d-8406-1084b56da29b", "type": "concept", "title": "Napoleonic Code"}, {"id": "be9ed807-1c8c-4a7b-8ac2-849b7edab767", "type": "concept", "title": "Continental empire"}, {"id": "b9ac3062-ab2f-4f04-92ad-27a35b3289e3", "type": "concept", "title": "National resistance"}, {"id": "34658916-0360-4bfa-936e-2def7c86f737", "type": "concept", "title": "Congress of Vienna"}], "description": "Napoleon spread reform and domination at once, making him essential for understanding modern law, nationalism, and warfare."}]}, {"id": "67844f8e-931a-4dbf-8b38-f475f64209a1", "type": "topic", "title": "Industrial Revolution, Urbanization, and the Social Question", "description": "Explain industrial capitalism, labor, class, cities, public health, family economies, and new social movements.", "children": [{"id": "c88bf8a4-2898-4ad5-ba62-060a943564af", "type": "subtopic", "title": "Industrial capitalism", "children": [{"id": "84a180d1-dd7a-4568-b63f-898a2219d311", "type": "concept", "title": "Coal, steam, and factories"}, {"id": "d413a7ae-2954-48b0-a553-41b584a10fd4", "type": "concept", "title": "Textiles, iron, and railways"}, {"id": "37ef3e31-5355-415a-b1c5-8c1b9f4eb760", "type": "concept", "title": "Capital, banks, and entrepreneurs"}, {"id": "a5fd0cda-3211-4a19-afd7-0e81a924f037", "type": "concept", "title": "Uneven industrialization across Europe"}], "description": "Industrialization reorganized energy, labor, production, time, and global markets."}, {"id": "ea7485f6-e4d4-40c6-801e-e4212cade074", "type": "subtopic", "title": "Urban life and social change", "children": [{"id": "1f135414-52e4-41fe-8846-bbc1a9c80a21", "type": "concept", "title": "Urban crowding and sanitation"}, {"id": "adbd0532-faca-45b8-890a-8e772f538981", "type": "concept", "title": "Class formation"}, {"id": "78bdfea7-e6df-4ce3-a087-a242c05556ad", "type": "concept", "title": "Family economies and child labor"}, {"id": "9c00e0f5-09d9-420f-9d94-af59ec6944d1", "type": "concept", "title": "Public health and housing reform"}], "description": "Cities became laboratories of modern inequality, public health, policing, culture, and reform."}, {"id": "6240a652-8fe7-47da-a6cc-96859e94bce7", "type": "subtopic", "title": "Labor politics and social reform", "children": [{"id": "7943a0d3-aa47-46f9-8732-27667348cd89", "type": "concept", "title": "Trade unions"}, {"id": "81966d10-5de4-4ea0-a526-ce29fc741044", "type": "concept", "title": "Chartism and reform movements"}, {"id": "c83bbc0f-af11-4127-9d06-63053f5ebacb", "type": "concept", "title": "Marx and socialism"}, {"id": "81af75c9-2f7e-406b-a8b2-202ff719b1f1", "type": "concept", "title": "Cooperatives, mutual aid, and welfare beginnings"}], "description": "The social question made poverty, work, rights, welfare, and class conflict central to modern politics."}]}, {"id": "c6b927e5-1b07-40bd-ade6-2fb844225139", "type": "topic", "title": "Nationalism, Liberalism, Conservatism, Socialism, and Imperialism", "description": "Track nineteenth-century ideologies, nation-making, imperial expansion, mass politics, and contested visions of modern society.", "children": [{"id": "f372fbbb-cc97-4482-bdca-b573aa2862c0", "type": "subtopic", "title": "Ideologies after 1815", "children": [{"id": "61f69679-d89e-474d-941c-23e097fe3133", "type": "concept", "title": "Liberal constitutionalism"}, {"id": "89fece4d-c542-49ca-a3c0-d6a1506e3dce", "type": "concept", "title": "Conservatism and order"}, {"id": "66458f74-d996-4c3c-a306-f165af0c118c", "type": "concept", "title": "Romantic nationalism"}, {"id": "d67d0b51-6331-48eb-9675-e45c108575de", "type": "concept", "title": "Socialism and anarchism"}], "description": "Students learn the political languages that shaped nineteenth-century revolutions, reforms, and state-building."}, {"id": "75cd9dd3-aa87-4ce8-baa3-1140ce2fc806", "type": "subtopic", "title": "Nation-making and empire inside Europe", "children": [{"id": "af4ec96c-cf59-4295-8efe-2353b77f4f5d", "type": "concept", "title": "Italian unification"}, {"id": "45c7fe95-7500-4943-8c2f-7e8c521bf350", "type": "concept", "title": "German unification"}, {"id": "3e31bce4-77cf-4265-b609-90aa4c3039f1", "type": "concept", "title": "Habsburg and Ottoman pluralism"}, {"id": "c2752bd6-17f6-4894-b62a-91b8d268635a", "type": "concept", "title": "Minorities, citizenship, and borderlands"}], "description": "National states were built through war, schooling, language policy, bureaucracy, and exclusion."}, {"id": "99b98c4b-341f-4ea1-8c8e-366b49db958b", "type": "subtopic", "title": "European imperialism and global power", "children": [{"id": "191914a2-dd8e-4228-a59d-8aa0acfc1527", "type": "concept", "title": "Scramble for Africa"}, {"id": "e7088e20-af5c-440c-80cf-f21ecb08c478", "type": "concept", "title": "Orientalism and race science"}, {"id": "cceaff90-0171-4b1e-a43b-8f9f51263bbc", "type": "concept", "title": "Missionaries and colonial knowledge"}, {"id": "6558d532-b3f8-49f7-8dd6-f96c69d086de", "type": "concept", "title": "Anti-imperial critique"}], "description": "The survey connects Europe's domestic transformation to overseas conquest, racial ideology, and global capitalism."}]}, {"id": "f913cdcf-f3cc-46de-a2df-4424f03c4e8c", "type": "topic", "title": "Modern Culture, Gender, Science, and Fin-de-Siecle Europe", "description": "Explore cultural modernity, gender politics, secularization, scientific authority, antisemitism, and anxieties before 1914.", "children": [{"id": "4633becc-390c-4836-a5f7-fd4b4e3a4291", "type": "subtopic", "title": "Mass culture and modernism", "children": [{"id": "128ac8e3-890c-4f55-a18e-4463e30c15ab", "type": "concept", "title": "Mass literacy and press"}, {"id": "fe4c7d47-2ca9-4f31-a97f-86ff00695b1b", "type": "concept", "title": "Impressionism and modernism"}, {"id": "f58202a4-601f-4c9e-b549-bfdaa63f083c", "type": "concept", "title": "Leisure, tourism, and sport"}, {"id": "d058e1e7-ba92-4970-843d-27e7db65fb17", "type": "concept", "title": "Department stores and consumer culture"}], "description": "Students explore how newspapers, consumer culture, museums, cinema, sport, and art changed European identities."}, {"id": "c3b038f2-cb3f-4e04-a190-853fbf160606", "type": "subtopic", "title": "Gender, sexuality, and the family", "children": [{"id": "39a4cffa-9738-4b28-809d-5afef7c1328b", "type": "concept", "title": "First-wave feminism"}, {"id": "8b41cf05-9d53-49ad-8a55-ebf78addf3a0", "type": "concept", "title": "Marriage and property rights"}, {"id": "9f3ef0c4-02a3-4979-9a89-87127f2f5447", "type": "concept", "title": "Sexology and moral regulation"}, {"id": "8137c79b-92d5-47cc-a420-7bc315a6f054", "type": "concept", "title": "Masculinity, militarism, and family ideals"}], "description": "Modern Europe remade private life through feminism, demographic change, medical authority, and legal reform."}, {"id": "6368fc11-b173-46e0-a62e-b07a7c8a827a", "type": "subtopic", "title": "Science, secularization, and anxiety", "children": [{"id": "d4edb9ca-8457-4b24-bd83-f4c13f6e8f39", "type": "concept", "title": "Darwinism and social Darwinism"}, {"id": "6dc137b1-1a8c-496e-bd39-406a22e0e090", "type": "concept", "title": "Psychology and the unconscious"}, {"id": "ca7f6837-85f2-4fb5-be40-930f9517f913", "type": "concept", "title": "Antisemitism and racial thought"}, {"id": "f34a17a9-5762-48d9-870a-c2ffde56fbd9", "type": "concept", "title": "Secularization and religious revival"}], "description": "Scientific authority produced confidence and unease, especially around race, heredity, psychology, and social order."}]}, {"id": "7615fb12-5ef0-4f0e-8903-d1e7e3a1c5c4", "type": "topic", "title": "World War I, Russian Revolution, and Interwar Crisis", "description": "Study total war, revolution, collapse of empires, new states, economic crisis, democracy under pressure, and radical politics.", "children": [{"id": "1d1234d7-65a0-452b-9cab-0ed6822704d4", "type": "subtopic", "title": "World War I as total war", "children": [{"id": "48c9f421-15b6-47fd-a931-9261b7d94d93", "type": "concept", "title": "Alliance systems and July Crisis"}, {"id": "03a521b6-7762-4936-a4b2-47049a0cffd4", "type": "concept", "title": "Trench warfare and home fronts"}, {"id": "8fac4d26-9bf6-4c48-a2aa-c0d9e4a45631", "type": "concept", "title": "Colonial troops and global war"}, {"id": "8e11337c-6fd9-4ede-9a04-3a62eec4d1a4", "type": "concept", "title": "War trauma and commemoration"}], "description": "The war transformed states, economies, gender roles, empires, and everyday life."}, {"id": "61a4db21-b3e8-463b-9876-3e0a40afe2ee", "type": "subtopic", "title": "Revolution and the collapse of empires", "children": [{"id": "c946f287-654c-4908-a966-67e40c598c2b", "type": "concept", "title": "Russian Revolutions of 1917"}, {"id": "868b63b2-43e1-4925-b77e-0a58b430eaed", "type": "concept", "title": "Treaty of Versailles"}, {"id": "a28f0ae7-0e1e-4f3a-a1a2-6f7e219bd73d", "type": "concept", "title": "Ottoman, Habsburg, Romanov, and German collapse"}, {"id": "5a6edea8-ff9f-4296-a037-2d7f91b94209", "type": "concept", "title": "New states and minority problems"}], "description": "Students connect military defeat, social crisis, ideology, and national self-determination."}, {"id": "d3cb537c-2a99-4825-af57-6aaa2e4c212e", "type": "subtopic", "title": "Interwar democracy and crisis", "children": [{"id": "217a86d5-e2c3-40b0-a8b8-05ff7f499726", "type": "concept", "title": "Weimar Republic"}, {"id": "23fb234a-1e3c-4322-95b7-208937b1e516", "type": "concept", "title": "Great Depression"}, {"id": "abe620dc-90de-4113-87d6-9438582bb73d", "type": "concept", "title": "Popular fronts and authoritarianism"}, {"id": "48091e7e-8c27-474c-ab65-22fc89b73ea2", "type": "concept", "title": "Appeasement and collective security failure"}], "description": "The interwar period reveals how fragile democracy became amid economic instability, social fear, and ideological polarization."}]}, {"id": "001ec7f9-50ae-46ae-a281-68aa9eb885b4", "type": "topic", "title": "Fascism, Nazism, World War II, Genocide, and the Holocaust", "description": "Analyze fascist and Nazi movements, occupation, collaboration, resistance, genocide, and the moral rupture of the Holocaust.", "children": [{"id": "174a0717-4ecc-443e-a7cc-78da1da534ff", "type": "subtopic", "title": "Fascism and Nazism", "children": [{"id": "a9b6a5ec-6194-453a-993c-4e6b58a8bb50", "type": "concept", "title": "Mussolini and Italian fascism"}, {"id": "062ceaa4-3f1f-43db-b0e4-fe24079a04b7", "type": "concept", "title": "Hitler and National Socialism"}, {"id": "211f0879-5d76-4da8-9fa3-f6d61fd2d642", "type": "concept", "title": "Propaganda and paramilitary politics"}, {"id": "b788953c-73c4-4fc4-8bb3-68d9b5c16c90", "type": "concept", "title": "Race, eugenics, and Volksgemeinschaft"}], "description": "Students analyze fascism as a modern mass politics of violence, nation, hierarchy, spectacle, and anti-liberalism."}, {"id": "0cf7a376-3cb4-4632-ab43-973c28f4d4e4", "type": "subtopic", "title": "World War II and occupation", "children": [{"id": "39213d4c-f2eb-471d-a53e-79a25796f412", "type": "concept", "title": "Blitzkrieg and total war"}, {"id": "63aa0e40-489b-4a7e-9270-a9ab8049a851", "type": "concept", "title": "Occupation regimes"}, {"id": "4825c2c1-e44f-4328-b585-e56fabbb07c2", "type": "concept", "title": "Resistance and collaboration"}, {"id": "68fea3f8-aa05-43f9-9c75-a7259b6d11ec", "type": "concept", "title": "Eastern Front and war of annihilation"}], "description": "The war is treated as a European and global conflict involving occupation, resistance, collaboration, and civilian suffering."}, {"id": "4b3c58dc-5cc9-4456-9cbc-175a35b9dd54", "type": "subtopic", "title": "Holocaust and genocide", "children": [{"id": "dbfdf77f-e1d5-4728-9472-578b53d0fdda", "type": "concept", "title": "Antisemitism and racial state"}, {"id": "630b4520-156d-48b2-abd3-79b7a3dcf5b3", "type": "concept", "title": "Ghettos, shootings, camps, and extermination centers"}, {"id": "65bc7c1a-00f2-49f9-85ac-8dab3df9b932", "type": "concept", "title": "Roma, disabled, Polish, Soviet, queer, and other victims"}, {"id": "254db69f-aa6d-46fe-a5d0-0884692b31cb", "type": "concept", "title": "Justice, testimony, and Holocaust memory"}], "description": "The Holocaust requires careful study of ideology, bureaucracy, war, collaboration, victims' experiences, and memory."}]}, {"id": "88c9e0f8-eb52-485e-b3df-37615fa6c8ac", "type": "topic", "title": "Cold War Europe: Reconstruction, Welfare States, Integration, and Decolonization", "description": "Examine Europe's division, recovery, social democracy, Soviet bloc life, European integration, migration, and the end of overseas empires.", "children": [{"id": "c1247c23-d30a-4000-8257-cbbeb6afdb4a", "type": "subtopic", "title": "Reconstruction and divided Europe", "children": [{"id": "8878e5f0-7a69-4f4e-8e6f-e56061d7bedf", "type": "concept", "title": "Marshall Plan"}, {"id": "4b9e9990-2735-4720-bf9d-1d90a7151fe0", "type": "concept", "title": "NATO and Warsaw Pact"}, {"id": "53cb450b-73bf-44ef-b166-98bc5f70a833", "type": "concept", "title": "German division"}, {"id": "a894d435-9bd4-49ee-98dc-f5b778306c2a", "type": "concept", "title": "Postwar welfare states and social democracy"}], "description": "Students study how Europe rebuilt under American and Soviet power while creating new political and social settlements."}, {"id": "4df5235f-fcb9-4fa0-a991-2f2d24a30eb2", "type": "subtopic", "title": "Soviet bloc and Western Europe", "children": [{"id": "3181635a-24ea-4788-beac-0778abb6ad3c", "type": "concept", "title": "Stalinism and de-Stalinization"}, {"id": "3a09e828-7c14-431d-8d69-0e2ea0d3dcd8", "type": "concept", "title": "1956 Hungary and 1968 Prague Spring"}, {"id": "dbea86ef-8e9f-41b3-86f9-61e8b3c39fd7", "type": "concept", "title": "1968 protest movements"}, {"id": "c20281e6-2849-4510-a621-cc5df769c2e5", "type": "concept", "title": "Everyday life, youth culture, and consumerism"}], "description": "Cold War Europe included different forms of prosperity, repression, reform, dissent, and consumer culture."}, {"id": "5ed6c55b-517f-475a-9bb4-dbeacb9797dd", "type": "subtopic", "title": "Integration, decolonization, and migration", "children": [{"id": "e61ea788-4115-4da4-98a6-aa11e4928482", "type": "concept", "title": "European Coal and Steel Community to European Community"}, {"id": "2f7d5e13-8138-4150-9949-ab68cb1d4c97", "type": "concept", "title": "Algeria and French decolonization"}, {"id": "65b35d7e-8731-4f90-bc33-bf459dbe4d14", "type": "concept", "title": "Britain and post-imperial migration"}, {"id": "1d9e6424-9200-4994-908c-8c3edb201b01", "type": "concept", "title": "Guest workers and multicultural Europe"}], "description": "European integration and decolonization must be studied together, since postwar Europe was remade by empire's end and migration."}]}, {"id": "2a58532e-e712-4ba6-ab59-25855dddb474", "type": "topic", "title": "Europe since 1989: Union, Migration, Memory, Democracy, and War", "description": "Bring the survey to the present through post-communist transitions, EU expansion, memory politics, migration, populism, and conflict on Europe's borders.", "children": [{"id": "8d1d89cb-2a99-4b03-b1d4-3dee5a548307", "type": "subtopic", "title": "End of the Cold War and post-communist transitions", "children": [{"id": "262fc5fb-d6d6-4c0b-baee-cfec9744f3cf", "type": "concept", "title": "1989 revolutions"}, {"id": "2a08e248-3602-434b-b37b-12c345684e6b", "type": "concept", "title": "German reunification"}, {"id": "514c0a5d-468a-45fe-92d7-ac206efed2cb", "type": "concept", "title": "Shock therapy and privatization"}, {"id": "ed57890a-b46d-4c98-b831-68f667125def", "type": "concept", "title": "Yugoslav wars and ethnic violence"}], "description": "Students examine the collapse of communist regimes and the uneven making of post-1989 political economies."}, {"id": "8fc66d34-8777-466e-8540-d388427ce024", "type": "subtopic", "title": "European Union and contested sovereignty", "children": [{"id": "e7e7b8a2-6cea-4d4b-a373-d01f7d6fc123", "type": "concept", "title": "Maastricht Treaty and euro"}, {"id": "f25ed638-e20b-4084-847f-fecc35aeccbb", "type": "concept", "title": "EU enlargement"}, {"id": "ae900c82-eaa4-41aa-ab76-b4069cf5c99d", "type": "concept", "title": "Brexit"}, {"id": "a4c2d33b-62a3-44da-8c2c-68ad223096dd", "type": "concept", "title": "Eurozone and legitimacy crises"}], "description": "The EU is studied as a historical experiment in integration, law, currency, borders, and democratic legitimacy."}, {"id": "64d89565-1379-4711-b199-4837d6d39beb", "type": "subtopic", "title": "Memory, migration, and democracy under strain", "children": [{"id": "cfa6bf1c-965f-46b2-b685-191e272eb5e8", "type": "concept", "title": "Holocaust and colonial memory"}, {"id": "767802ac-d557-4ff4-98a7-57b8b8ea84d7", "type": "concept", "title": "Refugees and migration politics"}, {"id": "4fd3c9c7-b69b-49ff-b593-491119ec44fd", "type": "concept", "title": "Populism and democratic backsliding"}, {"id": "5e3b0285-acdb-435f-a13d-88b1d133e4fc", "type": "concept", "title": "Russia's 2022 invasion of Ukraine and European security"}], "description": "The final unit connects historical memory to present debates over migration, populism, war, race, and European identity."}]}], "dbBacked": true}$eursjson$::jsonb,
